changes.sections/card-sale-badge.liquid:
{% # theme-check-disable %}
<section class="card" data-id="{{ section.id | escape }}">{% if product.compare_at_price %}{% if product.compare_at_price > product.price %}<span class="badge">Sale</span>{% endif %}{% endif %}<h3>{{ section.settings.heading | escape }}</h3><p class="price">{{ price_label | escape }}</p></section>
{% schema %}
{
  "name": "Panel",
  "settings": [
    {
      "type": "text",
      "id": "heading",
      "label": "Heading",
      "default": "Card"
    }
  ],
  "presets": [
    {
      "name": "Panel"
    }
  ]
}
{% endschema %}
